-- 0069 for staging or LIVE, all or nothing: no direct delete of a game (S1); notices: only read_at writable (S5)
-- Run once in Supabase → SQL Editor, in number order. Before the FIRST of the four: fixes_preflight.sql (all ok).
-- This script checks its own starting point and its own result; after the LAST: fixes_postcheck.sql (all ok).
-- Generated by supabase/live/make_fixes_apply.sh from supabase/migrations/0069_game_and_notification_writes.sql — do not edit by hand.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $pre$ begin
  if not (exists (select 1 from pg_policies where tablename = 'matches' and policyname = 'matches: organizer delete')
      and exists (select 1 from information_schema.column_privileges where table_schema = 'public' and table_name = 'notifications' and grantee = 'authenticated' and privilege_type = 'UPDATE' and column_name <> 'read_at')) then
    raise exception 'STOPPED, nothing changed: the objects 0069 replaces are not the verified 0001–0066 versions (already applied?)';
  end if;
end $pre$;
-- ===== migration 0069, unchanged from supabase/migrations/0069_game_and_notification_writes.sql =====
-- S1 and S5 (M3 safety review, brought forward by the release audit, 17 Nov 2026).
-- These two corrections were planned inside M3's hardening migration; that migration must not repeat
-- them (docs/audit/fixes.md, "M3 numbering").
--
-- S1: an organiser could delete a game row directly through the API. The cascade removed its players,
-- chat and notices without telling anyone, bypassing set_match_status (cancel notices, "cancel is
-- final"). Cancelling stays the only way to end a game; admin clean-up, if ever needed, goes through
-- the service role. No web or app code deletes from matches.
--
-- S5: signed-in users held UPDATE on every column of notifications, so a user could rewrite a notice's
-- text and clear emailed_at / email_claimed_at to put it back in the email queue. After this, the only
-- column a user can change is read_at (the policy "notifications: own mark read" still limits it to
-- their own rows). The web marks notices read through mark_notifications_read (security definer).
--
-- Safe to re-run.
drop policy if exists "matches: organizer delete" on matches;
revoke delete on matches from anon, authenticated;

revoke update on notifications from anon, authenticated;
grant update (read_at) on notifications to authenticated;
-- ===== end of migration 0069 =====
do $post$ begin
  if not (not exists (select 1 from pg_policies where tablename = 'matches' and cmd = 'DELETE')
      and not has_table_privilege('authenticated', 'public.matches', 'DELETE') and not has_table_privilege('anon', 'public.matches', 'DELETE')
      and (select string_agg(column_name, ',') from information_schema.column_privileges where table_schema = 'public' and table_name = 'notifications' and grantee = 'authenticated' and privilege_type = 'UPDATE') = 'read_at'
      and has_table_privilege('service_role', 'public.notifications', 'UPDATE')) then
    raise exception 'ROLLED BACK: the result of 0069 is not the verified version';
  end if;
end $post$;
notify pgrst, 'reload schema';
commit;
select '0069 applied' as result;
